from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_22R1 import SiteReset22R1


class SiteReset22R2(SiteReset22R1):

    def get_kpi(self):  # noqa: C901
        """
        Gets kpi for site reset operation.
        :return: dictionary with timeout, requirement and operation description for site reset
        :rtype: dict
        """
        use_restrictions = True

        if any(
            (
                all(
                    [
                        self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIL"]),
                        self.bts.number_of_bbmods <= 6,
                        self.bts.number_of_nr_cells <= 24,
                        self.bts.cell_technologies == "TDD",
                        self.bts.is_full_rack,
                        not self.bts.is_multi_rat,
                    ]
                ),
            )
        ):
            self.operation_details["Timeout"] = 504
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13561"

        elif all(
                [
                    "ASOE" in self.bts.smod_hw_types,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.14958"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods <= 6,
                    self.bts.cell_technologies == "TDD",
                    self.bts.number_of_bbmods == 1,
                    self.bts.setup_mode == "SA/NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15737"

        elif all(
                [
                    "ASIL" in self.bts.smod_hw_types or "ASIB" in self.bts.smod_hw_types,  # same for 22r3
                    self.bts.bbmod_hw_types == ["ABIN"],
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods == 1,
                    self.bts.radio_protocol == "CPRI",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15670"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIL"]),
                    self.bts.number_of_bbmods <= 2,
                    self.bts.number_of_nr_cells <= 2,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 396
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.14967"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIO"]),
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods <= 3,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15652"

        else:
            return super(SiteReset22R2, self).get_kpi()

        if use_restrictions:
            self.operation_details["Timeout"] += self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441()

        return self.operation_details
